"""Contract test: docs-sync step injection (spec 033 US3, migrated by 056 US3).

Originally driven by ``.specify/specs/033-docs-command/contracts/docs-step-injection.md``
(C-1…C-9): single source of truth ``shared/workflow/docs-step.md``, injected into the
complex command templates adjacent to ``## Feedback``. Since 056 the injection is
**compiled**: each subscribed unit's AUTO-GENERATED ``## Wrap-up`` carries one
``Docs Sync Eval`` call line citing this file, rendered by
``probe-utils.py --action compile-embeds`` from the registry's HandlerBinding rows
(22 per-command object rows); no manual ``## Documentation`` section exists anymore.

This scope is **not** the classification table's complex set. Not every complex command
is subscribed: ``history`` has a wrap-up face and no docs-sync line, so it is held out
in ``DOCS_STEP_EXCLUDED`` with a reason the suite re-measures — repairing the registry
without updating the dict goes red instead of drifting silently.
"""
from __future__ import annotations

import re
import runpy
from pathlib import Path

import pytest

REPO_ROOT = Path(__file__).resolve().parents[2]
COMMANDS_DIR = REPO_ROOT / "templates" / "commands"
SOURCE = REPO_ROOT / "shared" / "workflow" / "docs-step.md"
MIRROR = REPO_ROOT / ".specify" / "shared" / "workflow" / "docs-step.md"
CLASSIFICATION_TEST = REPO_ROOT / "tests" / "contract" / "test_feedback_command_classification.py"

COMPLEX_COMMANDS = [
    "requirements", "clarify", "plan", "tasks", "implement",
    "analyze", "checklist", "review", "research",
    "instructions", "tools", "skills", "todo", "docs",
    "interview", "derive",
    # `team` reclassified simple → complex on 2026-09-23 (user-adjudicated,
    # introspection-20260923T120035Z#F-02); see
    # tests/contract/test_feedback_command_classification.py for the criteria.
    "team",
    # Added 2026-09-24 on measurement: both already carried a correctly positioned
    # `## Documentation` and were the two of the four newly classified complex commands
    # that satisfied C-3 as written. The other two were repaired the same day.
    "goal", "session",
    # Added 2026-09-24 after repair: these two placed `## Documentation` *before*
    # `## Feedback`, which C-3's adjacency forbade; the sections were swapped in the
    # templates, and test_c2a then forced this list to be updated rather than drift.
    "feedback", "sanitize",
    # Added 2026-10-08 with the command itself (S4, session-driven-self-improvement).
    "improve",
]
SIMPLE_COMMANDS = ["agents", "constitution", "feature"]

# Complex commands held out of the docs-sync scope, each with a measured reason.
# ``test_c2a_exclusions_are_re_measured`` re-checks the reason against the compiled
# unit, so this dict cannot outlive the defect it documents.
DOCS_STEP_EXCLUDED = {
    "history": "no-documentation-section",
}

# Anti-vacuity sentinel: an empty or truncated scope list would make every
# per-command assertion below pass without a single template being read.
MIN_COMPLEX = 21

DOCS_LINE_MARKER = "Docs Sync Eval"
BANNER = "AUTO-GENERATED by probe-utils.py --action compile-embeds"


def classification_complex() -> set[str]:
    """The classification contract's complex set, via its owning test module."""
    return set(runpy.run_path(str(CLASSIFICATION_TEST))["COMPLEX_COMMANDS"])


def wrapup_section(text: str) -> str:
    m = re.search(r"^## Wrap-up$(.*?)(?=^## |\Z)", text, re.M | re.S)
    assert m, "missing ## Wrap-up"
    return m.group(1)


def docs_scope_by_compiled_line() -> set[str]:
    """Command templates whose compiled Wrap-up carries the Docs Sync Eval call
    line — the measured docs-sync scope after 056."""
    out = set()
    for path in COMMANDS_DIR.glob("*.md"):
        text = path.read_text(encoding="utf-8")
        if re.search(r"^## Wrap-up$", text, re.M) and DOCS_LINE_MARKER in wrapup_section(text):
            out.add(path.stem)
    return out


@pytest.mark.contract
def test_c1_single_source_and_mirror():
    assert SOURCE.is_file(), "shared/workflow/docs-step.md missing"
    assert MIRROR.is_file(), ".specify mirror missing"
    assert SOURCE.read_bytes() == MIRROR.read_bytes(), "docs-step mirror drift"


@pytest.mark.contract
def test_c2_injection_scope_counts():
    assert len(SIMPLE_COMMANDS) == 3
    # No exact count for COMPLEX_COMMANDS on purpose: test_c2b derives the scope from
    # the classification table minus the re-measured exclusions, which is a stronger
    # check, and a second hard-coded number here would only drift against it. What this
    # guard owns is truncation — an empty or short list makes every per-command
    # assertion below pass without reading a single template.
    assert len(COMPLEX_COMMANDS) >= MIN_COMPLEX, (
        f"scope list holds {len(COMPLEX_COMMANDS)} entries (< {MIN_COMPLEX}) — it looks "
        f"truncated, which would make the per-command assertions below vacuous"
    )


@pytest.mark.contract
def test_c2a_exclusions_are_re_measured():
    """Every held-out command must still exhibit the reason it is held out for."""
    for cmd, reason in DOCS_STEP_EXCLUDED.items():
        text = (COMMANDS_DIR / f"{cmd}.md").read_text(encoding="utf-8")
        if reason == "no-documentation-section":
            assert re.search(r"^## Wrap-up$", text, re.M), \
                f"{cmd}.md lost its wrap-up face — re-register it or update the reason"
            assert DOCS_LINE_MARKER not in wrapup_section(text), (
                f"{cmd}.md's compiled Wrap-up now carries the docs-sync line — remove it "
                f"from DOCS_STEP_EXCLUDED and add it to COMPLEX_COMMANDS"
            )
        else:
            pytest.fail(f"unknown exclusion reason for {cmd}: {reason!r}")


@pytest.mark.contract
def test_c2b_scope_is_classification_minus_verified_exclusions():
    """No complex command is silently dropped from the docs-sync scope."""
    expected = classification_complex() - set(DOCS_STEP_EXCLUDED)
    assert set(COMPLEX_COMMANDS) == expected, (
        f"docs-sync scope drift — missing: {sorted(expected - set(COMPLEX_COMMANDS))}; "
        f"extra: {sorted(set(COMPLEX_COMMANDS) - expected)}"
    )
    assert set(COMPLEX_COMMANDS) == docs_scope_by_compiled_line(), (
        "the scope list and the measured set of units whose compiled Wrap-up carries "
        "the Docs Sync Eval line disagree — registry HandlerBinding rows and this list "
        "must move together"
    )


@pytest.mark.contract
@pytest.mark.parametrize("cmd", COMPLEX_COMMANDS)
def test_c3_c4_documentation_section_position_and_reference(cmd: str):
    text = (COMMANDS_DIR / f"{cmd}.md").read_text(encoding="utf-8")
    assert re.search(r"^## Wrap-up$", text, re.M), f"{cmd}.md missing the compiled Wrap-up"
    assert BANNER in text, f"{cmd}.md Wrap-up must be AUTO-GENERATED (compiled, not hand-embedded)"
    body = wrapup_section(text)
    assert DOCS_LINE_MARKER in body, f"{cmd}.md Wrap-up missing the Docs Sync Eval call line"
    assert "docs-step.md" in body, f"{cmd}.md docs-sync line must cite docs-step.md"
    # 063 C-20/C-21 amendment (2026-10-20): engine lines render the full
    # args-manifest inline; the compiled command face grew to ~1777 B. Budget
    # raised 1500 -> 2500; the reference-not-copy intent stays (docs-step.md
    # cite + marker assertions above unchanged).
    assert len(body) < 2500, f"{cmd}.md Wrap-up must reference, not copy, the rules"


@pytest.mark.contract
@pytest.mark.parametrize("cmd", SIMPLE_COMMANDS)
def test_c2_simple_commands_not_injected(cmd: str):
    text = (COMMANDS_DIR / f"{cmd}.md").read_text(encoding="utf-8")
    assert "## Documentation" not in text, f"{cmd}.md must not carry the docs-sync step"
    assert "## Wrap-up" not in text, f"{cmd}.md is not a registered unit and must have no wrap-up face"


@pytest.mark.contract
def test_c6_c7_incremental_and_zero_new_machinery():
    text = SOURCE.read_text(encoding="utf-8")
    assert "R0" in text and "NEVER trigger" in text, "incremental-only rule missing"
    assert "Non-blocking" in text
    assert "Zero new machinery" in text
    # The conclusion contract moved wholly into the owner when the manual sections
    # were compiled away (056): the per-unit pointer no longer restates it.
    assert "需记录" in text and "无需记录" in text, \
        "docs-step.md lost the conclusion contract (需记录 / 无需记录)"
